import { readFile, mkdtemp, rm, writeFile, readdir, stat } from 'node:fs/promises';
import { createHash } from 'node:crypto';
import { execFileSync } from 'node:child_process';
import { cpus, tmpdir } from 'node:os';
import { join } from 'node:path';
import { pathToFileURL } from 'node:url';
const [root, output] = process.argv.slice(2);
const moduleAt = p => import(pathToFileURL(join(root, p)));
const [{ planLeague }, { reserveLeaguePartition, runLeaguePartition }, { Measurements }, { BattleBundles }, { leagueEstimate }] = await Promise.all([
  moduleAt('apps/api/src/league/league-plan.ts'), moduleAt('apps/api/src/league/league-runner.ts'),
  moduleAt('apps/api/src/measurements.ts'), moduleAt('apps/api/src/batch/battle-bundle.ts'),
  moduleAt('apps/api/test-support/leagues.ts'),
]);
const sha = execFileSync('git', ['rev-parse', 'HEAD'], { cwd: root, encoding: 'utf8' }).trim();
if (execFileSync('git', ['status', '--porcelain'], { cwd: root, encoding: 'utf8' }).trim()) throw Error('Dirty source');
const input = JSON.parse(await readFile(join(root, 'data/leagues/official-20-v2.json'), 'utf8'));
input.id = 'l5-02-queue-pilot'; input.name = 'Producer pipeline pilot';
input.characters = input.characters.filter(c => ['guardian', 'fire-mage'].includes(c.id));
if (input.characters.length !== 2 || input.battlefields.length !== 5) throw Error('Pilot input changed');
input.trials = 1;
const source = { sha, node: process.versions.node, platform: process.platform, arch: process.arch };
const { plan, partitions } = await planLeague(input, source, leagueEstimate);
if (partitions.length !== 1 || partitions[0].batch.slots.length !== 10) throw Error('Expected ten-match partition');
const { partition, batch } = partitions[0];
const reservation = await reserveLeaguePartition(plan, partition, [], 'queue-pilot');
const target = await mkdtemp(join(tmpdir(), 'l5-queue-pilot-'));
const hash = bytes => createHash('sha256').update(bytes).digest('hex');
const record = { source, driverSha256: hash(await readFile(new URL(import.meta.url))), lockSha256: hash(await readFile(join(root, 'pnpm-lock.yaml'))), inputSha256: hash(JSON.stringify(input)), inputFileSha256: hash(await readFile(join(root, 'data/leagues/official-20-v2.json'))), cpuModel: cpus()[0]?.model,
  note: '10 new matches from official-20-v2: guardian/fire-mage, all five real fields, both placements, one trial; unchanged 6000-step rules/budget. Two Workers. Preparation/startup/output comparison excluded. Fresh empty output per process. No R2/Pages/full-league acceptance.' };
const measurements = new Measurements();
async function sizes(directory) {
  let bytes = 0, files = 0;
  for (const entry of await readdir(directory, { withFileTypes: true })) {
    const p = join(directory, entry.name);
    if (entry.isDirectory()) { const child = await sizes(p); bytes += child.bytes; files += child.files; }
    else { bytes += (await stat(p)).size; files++; }
  }
  return { bytes, files };
}
try {
  const result = await measurements.run(() => runLeaguePartition(plan, partition, batch, reservation, target, source, 'queue-pilot', { workers: 2 }));
  record.measurement = measurements.report(); record.processMaxRssKiB = process.resourceUsage().maxRSS;
  const bundles = new BattleBundles(join(target, 'bundles'));
  record.outputs = [];
  for (const slot of result.index.slots) {
    if (!slot.receipt) throw Error('Unpublished slot: ' + slot.state + ' ' + slot.reason);
    const manifest = await bundles.manifest(slot.receipt);
    record.outputs.push({ slot: slot.slotId, simulation: slot.simulationHash, state: slot.state, reused: slot.reused, resultHash: slot.receipt.resultHash, chunks: manifest.chunks.map(x => x.checksum), checkpoints: manifest.checkpoints.map(x => x.checksum) });
  }
  record.complete = result.index.complete;
  record.finalWorkDirectory = await sizes(join(target, 'bundles', '.work'));
  record.finalDirectory = await sizes(target);
} catch (error) { record.failure = String(error); record.measurement = measurements.report(); process.exitCode = 1; }
finally { await rm(target, { recursive: true, force: true }); await writeFile(output, JSON.stringify(record, null, 2) + '\n'); }

