import json,subprocess,datetime,os
from pathlib import Path
repository=Path('/workspace/scratch/a9b26faae556/FantasySimulation')
folder=repository/'.generated/queue-pilot'
plan=json.loads((folder/'plan.json').read_text())
roots={'baseline':Path('/workspace/scratch/a9b26faae556/FantasySimulation-l5-02'),'candidate':repository}
node='/opt/codex/runtimes/codex-primary-runtime/dependencies/node/bin/node'
for i,trial in enumerate(plan['trials']):
 if (folder/'STOP').exists():
  print('Stopped before trial',i,flush=True); break
 root=roots[trial['variant']]; name=f"{i:02}-{trial['phase']}-{trial['pair']}-{trial['variant']}"; output=folder/(name+'.json')
 command=[node,'--import','tsx',str(repository/'.generated/l5-queue-pilot.mjs'),str(root),str(output)]
 started=datetime.datetime.now(datetime.timezone.utc).isoformat()
 try:
  process=subprocess.run(command,cwd=root/'apps/cli',capture_output=True,text=True,timeout=plan['trialWallLimitSeconds'])
  code=process.returncode; stdout=process.stdout; stderr=process.stderr; timedOut=False
 except subprocess.TimeoutExpired as e:
  code=None; timedOut=True; stdout=e.stdout or b''; stderr=e.stderr or b''
  if isinstance(stdout,bytes): stdout=stdout.decode(errors='replace')
  if isinstance(stderr,bytes): stderr=stderr.decode(errors='replace')
 receipt={**trial,'startedAt':started,'finishedAt':datetime.datetime.now(datetime.timezone.utc).isoformat(),'command':command,'workingDirectory':str(root/'apps/cli'),'exitCode':code,'timedOut':timedOut,'output':output.name if output.exists() else None}
 (folder/(name+'.receipt.json')).write_text(json.dumps(receipt,indent=2)+'\n')
 (folder/(name+'.log')).write_text(stdout+'\n'+stderr)
 value=json.loads(output.read_text()) if output.exists() else {}
 print(name,'exit',code,'wallMs',value.get('measurement',{}).get('wallMs'),'failure',value.get('failure'),'timeout',timedOut,flush=True)
